import random, time, sys
MOD=998244353
def solve(N, P):
    # P: list of (X,Y) 1-based
    ys=[0]*N
    for X,Y in P: ys[X-1]=Y-1
    Cm=[0]*N
    for x in range(N):
        m=0
        for q in range(N):
            if (q-x)*(ys[q]-ys[x])>0: m|=1<<q
        Cm[x]=m
    PY=[0]*(N+1)
    for k in range(N):
        PY[k+1]=PY[k]|(1<<ys.index(k))
    def region(xlo,xhi,ylo,yhi):
        if xlo>xhi or ylo>yhi: return 0
        XR=((1<<(xhi+1))-1)^((1<<xlo)-1)
        YR=PY[yhi+1]^PY[ylo]
        return XR&YR
    def good(M):
        m=M
        while m:
            low=m&-m
            p=low.bit_length()-1
            if not (Cm[p]&M): return False
            m^=low
        return True
    f=[0]*N
    for b in range(N):
        val=1 if good(region(0,b-1,ys[b]+1,N-1)) else 0
        s=val
        for a in range(b):
            if ys[a]>ys[b] and good(region(a+1,b-1,ys[b]+1,ys[a]-1)):
                s+=f[a]
        f[b]=s%MOD
    ans=1 if good(region(0,N-1,0,N-1)) else 0
    for b in range(N):
        if good(region(b+1,N-1,0,ys[b]-1)):
            ans+=f[b]
    return ans%MOD

def brute(N,P):
    full=frozenset(range(N))
    seen={full}
    st=[full]
    while st:
        R=st.pop()
        for k in R:
            Xk,Yk=P[k]
            NR=frozenset(i for i in R if not ((P[i][0]<Xk and P[i][1]<Yk) or (P[i][0]>Xk and P[i][1]>Yk)))
            if NR not in seen:
                seen.add(NR); st.append(NR)
    return len(seen)%MOD

