import numpy as np
MOD=998244353
def solve(N,A):
    fac={}
    for i,a in enumerate(A):
        x=a; d=2
        while d*d<=x:
            if x%d==0:
                c=0
                while x%d==0: x//=d; c+=1
                fac.setdefault(d,[0]*(N-1))[i]=c
            d+=1
        if x>1: fac.setdefault(x,[0]*(N-1))[i]=1
    ans=1
    for p,ks in fac.items():
        S=sum(ks); size=2*S+1
        pw=np.ones(size,dtype=np.int64)
        for e in range(1,size): pw[e]=pw[e-1]*p%MOD
        def run(L0):
            f=np.zeros(size,dtype=np.int64)
            for h in range(L0,S+1): f[h]=pw[h]
            for k in ks:
                if k==0:
                    f=f*pw%MOD
                else:
                    g=np.zeros(size,dtype=np.int64)
                    g[k:]+=f[:-k]
                    g[:-k]+=f[k:]
                    g%=MOD
                    g[:L0]=0
                    f=g*pw%MOD
            return int(f.sum()%MOD)
        ans=ans*((run(0)-run(1))%MOD)%MOD
    return ans
