import math
def brute(N,A,LIM):
    opts=[]
    for a in A:
        o=[]
        for P in range(1,a+1):
            if a%P==0:
                Q=a//P
                if math.gcd(P,Q)==1: o.append((P,Q))
        opts.append(o)
    total=0
    def rec(seq,i):
        nonlocal total
        if i==N-1:
            g=0
            for s in seq: g=math.gcd(g,s)
            if g==1:
                pr=1
                for s in seq: pr*=s
                total+=pr
            return
        for P,Q in opts[i]:
            if (seq[-1]*Q)%P==0:
                nx=seq[-1]*Q//P
                if nx<=LIM: rec(seq+[nx],i+1)
    for s1 in range(1,LIM+1): rec([s1],0)
    return total
