from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        m = len(conflictingPairs)
        byb = [[] for _ in range(n+1)]
        for i,(x,y) in enumerate(conflictingPairs):
            a,b = min(x,y), max(x,y)
            byb[b].append((a,i))
        gain = [0]*m
        v1, id1, v2 = 0, -1, 0
        total = 0
        for r in range(1, n+1):
            for a,i in byb[r]:
                if a > v1:
                    v2 = v1; v1 = a; id1 = i
                elif a > v2:
                    v2 = a
            total += r - v1
            if id1 >= 0:
                gain[id1] += v1 - v2
        return total + max(0, max(gain))

