def lis(seq, strict_inc=True):
    # longest increasing (sign=+1) subsequence
    n=len(seq); d=[]
    import bisect
    for v in seq:
        i=bisect.bisect_left(d,v)
        if i==len(d): d.append(v)
        else: d[i]=v
    return len(d)
