from typing import List
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        D = [(1,1),(1,-1),(-1,-1),(-1,1)]
        nv = {1:2, 2:0, 0:2}
        partner = {2:0, 0:2}
        E = []
        B = []
        for dr, dc in D:
            Ek = [[0]*m for _ in range(n)]
            rows = range(n) if dr == 1 else range(n-1, -1, -1)
            cols = range(m) if dc == 1 else range(m-1, -1, -1)
            for r in rows:
                for c in cols:
                    v = grid[r][c]
                    if v == 1:
                        Ek[r][c] = 1
                    else:
                        pr, pc = r-dr, c-dc
                        if 0 <= pr < n and 0 <= pc < m:
                            p = Ek[pr][pc]
                            if p and v == nv[grid[pr][pc]]:
                                Ek[r][c] = p+1
            E.append(Ek)
            Bk = [[0]*m for _ in range(n)]
            rows = range(n-1, -1, -1) if dr == 1 else range(n)
            cols = range(m-1, -1, -1) if dc == 1 else range(m)
            for r in rows:
                for c in cols:
                    v = grid[r][c]
                    if v == 1:
                        continue
                    nr, nc = r+dr, c+dc
                    b = 0
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == partner[v]:
                        b = Bk[nr][nc]
                    Bk[r][c] = 1 + b
            B.append(Bk)
        ans = 0
        for k in range(4):
            k2 = (k+1) % 4
            for r in range(n):
                for c in range(m):
                    e = E[k][r][c]
                    if e == 0:
                        continue
                    if e > ans: ans = e
                    nr, nc = r+D[k2][0], c+D[k2][1]
                    if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == nv[grid[r][c]]:
                        t = e + B[k2][nr][nc]
                        if t > ans: ans = t
        return ans

