from typing import List
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def W(o, e, last):
            if o + e == 0:
                return 1
            if last == 1:
                return e * W(o, e - 1, 0) if e > 0 else 0
            else:
                return o * W(o - 1, e, 1) if o > 0 else 0
        odd_left = (n + 1) // 2
        even_left = n // 2
        used = [False] * (n + 1)
        if k > sum(W(odd_left - (v % 2), even_left - (1 - v % 2), v % 2) for v in range(1, n + 1)):
            return []
        res = []
        last = None
        for pos in range(n):
            for v in range(1, n + 1):
                if used[v]:
                    continue
                p = v % 2
                if last is not None and p == last:
                    continue
                o = odd_left - p
                e = even_left - (1 - p)
                c = W(o, e, p)
                if k > c:
                    k -= c
                else:
                    used[v] = True
                    res.append(v)
                    odd_left, even_left = o, e
                    last = p
                    break
        return res

