class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        pw = [0] * n
        p10 = 1 % k
        for i in range(n):
            pw[i] = p10
            p10 = p10 * 10 % k
        w = [0] * h
        for p in range(h):
            q = n - 1 - p
            w[p] = (pw[p] + pw[q]) % k if p != q else pw[p] % k
        full = (1 << k) - 1
        reach = [0] * (h + 1)
        reach[h] = 1
        for i in range(h - 1, -1, -1):
            m = reach[i + 1]
            r = 0
            for d in range(10):
                a = d * w[i] % k
                if a == 0:
                    r |= m
                else:
                    r |= ((m << a) | (m >> (k - a))) & full
            reach[i] = r
        half = []
        cur = 0
        for p in range(h):
            lo = 1 if p == 0 else 0
            for d in range(9, lo - 1, -1):
                t = (cur + d * w[p]) % k
                need = (-t) % k
                if (reach[p + 1] >> need) & 1:
                    half.append(d)
                    cur = t
                    break
        s = ''.join(map(str, half))
        return s + s[:n // 2][::-1]

