class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        ng = [n]*n
        st = []
        for i in range(n-1, -1, -1):
            while st and nums[st[-1]] <= nums[i]:
                st.pop()
            ng[i] = st[-1] if st else n
            st.append(i)
        D = [0]*(n+1)
        for c in range(n-1, -1, -1):
            D[c] = nums[c]*(ng[c]-c) + D[ng[c]]
        P = [0]*(n+1)
        for i in range(n):
            P[i+1] = P[i] + nums[i]
        LOG = max(1, (n+1).bit_length())
        up = [ng + [n]]
        for j in range(1, LOG):
            prev = up[-1]
            up.append([prev[prev[c]] for c in range(n+1)])
        def cost(l, r):
            c = l
            for j in range(LOG-1, -1, -1):
                nx = up[j][c]
                if nx <= r:
                    c = nx
            F = (D[l]-D[c]) + nums[c]*(r+1-c)
            return F - (P[r+1]-P[l])
        total = 0
        r = -1
        for l in range(n):
            if r < l-1:
                r = l-1
            while r+1 < n and cost(l, r+1) <= k:
                r += 1
            total += r-l+1
        return total

