from typing import List

class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        adj = [[] for _ in range(n)]
        for u, v, w in edges:
            adj[u].append((v, w)); adj[v].append((u, w))
        parent = [-1] * n
        order = []
        visited = [False] * n
        visited[0] = True
        stack = [0]
        while stack:
            v = stack.pop()
            order.append(v)
            for to, w in adj[v]:
                if not visited[to]:
                    visited[to] = True
                    parent[to] = v
                    stack.append(to)
        d0 = [0] * n
        d1 = [0] * n
        for v in reversed(order):
            base = 0
            gains = []
            pv = parent[v]
            for to, w in adj[v]:
                if to != pv:
                    base += d0[to]
                    gains.append(d1[to] + w - d0[to])
            gains.sort(reverse=True)
            s0 = base; s1 = base
            for i, g in enumerate(gains):
                if g <= 0:
                    break
                if i < k:
                    s0 += g
                if i < k - 1:
                    s1 += g
            d0[v] = s0; d1[v] = s1
        return d0[0]

