from functools import lru_cache

def calc(A):
    n = len(A)
    order = sorted(range(n), key=A.__getitem__)
    rank = [0]*n
    for r, i in enumerate(order):
        rank[i] = r+1
    cnt = [0]*(n+1); sm = [0]*(n+1)
    LOG = 1
    while LOG*2 <= n: LOG *= 2
    res = [0]*(n+1)
    total = 0
    for m in range(1, n+1):
        v = A[m-1]; total += v
        p = rank[m-1]
        while p <= n:
            cnt[p] += 1; sm[p] += v; p += p & -p
        if m % 2 == 0:
            rem = m//2; pos = 0; s = 0; step = LOG
            while step:
                q = pos+step
                if q <= n and cnt[q] <= rem:
                    pos = q; rem -= cnt[q]; s += sm[q]
                step >>= 1
            res[m] = total - 2*s
    return res

def solve(n, A):
    P = calc(A)
    if n % 2 == 0:
        return P[n]
    S = calc(A[::-1])
    best = None
    for i in range(0, n, 2):
        val = P[i] + S[n-1-i]
        if best is None or val > best: best = val
    return best

def brute(A):
    @lru_cache(None)
    def go(t):
        if len(t) <= 1: return 0
        best = -1
        for i in range(len(t)-1):
            v = abs(t[i]-t[i+1]) + go(t[:i]+t[i+2:])
            best = max(best, v)
        return best
    return go(tuple(A))

