import bisect

def occ(t, pat):
    n, m = len(t), len(pat)
    if m == 0:
        return list(range(n + 1))
    f = [0] * m
    k = 0
    for i in range(1, m):
        while k and pat[i] != pat[k]:
            k = f[k - 1]
        if pat[i] == pat[k]:
            k += 1
        f[i] = k
    res = []
    k = 0
    for i, ch in enumerate(t):
        while k and ch != pat[k]:
            k = f[k - 1]
        if ch == pat[k]:
            k += 1
        if k == m:
            res.append(i - m + 1)
            k = f[k - 1]
    return res

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        i1 = p.index('*')
        i2 = p.index('*', i1 + 1)
        A, B, C = p[:i1], p[i1+1:i2], p[i2+1:]
        OA = occ(s, A); OB = occ(s, B); OC = occ(s, C)
        if not OB:
            return -1
        best = None
        la, lb, lc = len(A), len(B), len(C)
        for k in OB:
            idx = bisect.bisect_right(OA, k - la) - 1
            if idx < 0:
                continue
            a = OA[idx]
            idx2 = bisect.bisect_left(OC, k + lb)
            if idx2 >= len(OC):
                continue
            L = OC[idx2] + lc - a
            if best is None or L < best:
                best = L
        return -1 if best is None else best

