    data = sys.stdin.read().split()
    K = int(data[0]); S = data[1]; T = data[2]
    n, m = len(S), len(T)
    if abs(n - m) > K:
        print("No"); return
    MOD = (1 << 61) - 1
    B = random.randrange(10**6, 10**9)
    def build(X):
        H = [0] * (len(X) + 1)
        h = 0
        for idx, c in enumerate(X):
            h = (h * B + ord(c)) % MOD
            H[idx + 1] = h
        return H
    HS = build(S); HT = build(T)
    P = [1] * (max(n, m) + 1)
    for i in range(1, len(P)):
        P[i] = P[i - 1] * B % MOD
    def eq(a, b, L):
        return (HS[a + L] - HS[a] * P[L] - HT[b + L] + HT[b] * P[L]) % MOD == 0
    def slide(i, k):
        j = i + k
        hi = min(n - i, m - j)
        lo = 0
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if eq(i, j, mid):
                lo = mid
            else:
                hi = mid - 1
        return i + lo
    NEG = -10**9
    target = m - n
    prev = {k: NEG for k in range(-K - 1, K + 2)}
    prev[0] = slide(0, 0)
    if abs(target) <= K and prev[target] >= n:
        print("Yes"); return
    for e in range(1, K + 1):
        cur = {k: NEG for k in range(-K - 1, K + 2)}
        for k in range(-K, K + 1):
