from typing import List
class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        INF = float('inf')
        mn = [INF] * k
        ans = -INF
        p = 0
        for i in range(n + 1):
            if i > 0:
                p += nums[i - 1]
            r = i % k
            if mn[r] != INF:
                v = p - mn[r]
                if v > ans:
                    ans = v
            if p < mn[r]:
                mn[r] = p
        return int(ans)

