def brute(nums, queries):
    n = len(nums)
    cur = [set([0]) for _ in range(n)]  # reachable total decrements per index
    def done(c):
        return all(nums[i] in c[i] for i in range(n))
    if done(cur): return 0
    for k,(l,r,v) in enumerate(queries,1):
        new = [set(s) for s in cur]
        idx = list(range(l,r+1))
        for mask in range(1<<len(idx)):
            for j,i in enumerate(idx):
                if mask>>j &1:
                    for s in cur[i]:
                        new[i].add(s+v)
        cur = new
        if done(cur): return k
    return -1

