class Solution:
    def minOperations(self, n: int, m: int) -> int:
        L = len(str(n))
        N = 10**L
        isp = [True]*N
        isp[0] = False
        isp[1] = False
        for i in range(2, int(N**0.5)+1):
            if isp[i]:
                for j in range(i*i, N, i):
                    isp[j] = False
        if isp[n] or isp[m]:
            return -1
        INF = float('inf')
        dist = [INF]*N
        dist[n] = n
        pq = [(n, n)]
        while pq:
            d, v = heapq.heappop(pq)
            if d != dist[v]:
                continue
            if v == m:
                return d
            p = 1
            for _ in range(L):
                dig = (v // p) % 10
                for nd in (dig-1, dig+1):
                    if 0 <= nd <= 9:
                        u = v + (nd-dig)*p
                        if isp[u]:
                            continue
                        if d+u < dist[u]:
                            dist[u] = d+u
                            heapq.heappush(pq, (d+u, u))
                p *= 10
        return -1

