class Solution:
    def beautifulSplits(self, nums):
        n = len(nums)
        z = [0]*n
        z[0] = n
        l = r = 0
        for i in range(1, n):
            if i < r:
                z[i] = min(r-i, z[i-l])
            while i+z[i] < n and nums[z[i]] == nums[i+z[i]]:
                z[i] += 1
            if i+z[i] > r:
                l, r = i, i+z[i]
        total = 0
        prev = []
        for i in range(n-1, 0, -1):
            a = nums[i]
            cur = [p+1 if x == a else 0 for x, p in zip(nums[i+1:], prev+[0])]
            prev = cur
            D = (n-i)//2
            total += sum(1 for k in range(D) if cur[k] >= k+1)
            if z[i] >= i:
                total += max(0, n-2*i)
                total -= sum(1 for k in range(i-1, D) if cur[k] >= k+1)
        return total

