        cnt = [0]*n
        for a, b, w in kept: cnt[a] += 1
        if any(c > t for c in cnt): continue
        # reachability to 0
        adj = [[] for _ in range(n)]
        for a, b, w in kept: adj[a].append(b)
        ok = True
        for s in range(1, n):
            seen = {s}; st = [s]; found = False
            while st:
                u = st.pop()
                if u == 0: found = True; break
                for v in adj[u]:
                    if v not in seen: seen.add(v); st.append(v)
            if not found: ok = False; break
        if not ok: continue
        mx = max((w for _, _, w in kept), default=0)
        if best == -1 or mx < best: best = mx
    return best

