        INF = float('inf')
        d = [INF] * n
        d[0] = 0
        h = [(0, 0)]
        while h:
            dx, x = heapq.heappop(h)
            if dx > d[x]:
                continue
            for a, w in inc[x]:
                nd = dx if dx > w else w
                if nd < d[a]:
                    d[a] = nd
                    heapq.heappush(h, (nd, a))
        if any(v == INF for v in d):
            return -1
        return max(d)

