from typing import List
import itertools

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        pts = set(map(tuple, points))
        P = list(pts)
        best = -1
        for (x1, y1), (x2, y2) in itertools.combinations(P, 2):
            if x1 == x2 or y1 == y2:
                continue
            xl, xh = min(x1, x2), max(x1, x2)
            yl, yh = min(y1, y2), max(y1, y2)
            if (xl, yl) not in pts or (xl, yh) not in pts or (xh, yl) not in pts or (xh, yh) not in pts:
                continue
            ok = True
            for (px, py) in P:
                if xl <= px <= xh and yl <= py <= yh and (px, py) not in ((xl, yl), (xl, yh), (xh, yl), (xh, yh)):
                    ok = False
                    break
            if ok:
                best = max(best, (xh - xl) * (yh - yl))
        return best

